(() => {
'use strict';
const F=window.EVAL_FIXTURES, app=document.querySelector('#app'), params=new URLSearchParams(location.search);
const screens={menu:['main','compose','pending','offline','empty','accepted'],dashboard:['live','stale','surge'],bank:['welcome','details','details-error','code','code-error','help','done']};
let state=params.get('screen')||'main';if(!Object.values(screens).flat().includes(state))state='main';
let family=Object.keys(screens).find(k=>screens[k].includes(state));
const theme=params.get('theme');const media=matchMedia('(prefers-color-scheme: dark)');
function setTheme(){document.documentElement.dataset.theme=theme==='light'||theme==='dark'?theme:(media.matches?'dark':'light')};setTheme();media.addEventListener('change',setTheme);
document.body.className=family;document.body.dataset.display=params.get('display')==='tv'?'tv':'laptop';
let recipient='',note='',review=false,customer='',mobile='',code='',nameError='',mobileError='',codeError='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(type='rota')=>`<span class="mark" aria-hidden="true"><svg viewBox="0 0 24 24">${type==='bank'?'<path d="M3 17h18M5 13l7-8 7 8M8 17V9m8 8V9M3 21h18"/>':type==='dash'?'<path d="M3 17V7m6 14V3m6 14V7m6 7v-4"/>':'<path d="M5 7h11l-3-3m6 13H8l3 3M19 7v5M5 17v-5"/>'}</svg></span>`;
function go(next,focus=true){state=next;params.set('screen',state);history.replaceState(null,'',`${location.pathname}?${params}`);render();if(focus){const target=app.querySelector('h1');target?.setAttribute('tabindex','-1');target?.focus({preventScroll:true});}window.scrollTo(0,0);}
function button(text,action,cls=''){return `<button class="${cls}" data-action="${action}">${text}</button>`}
function footer(text='Current on-call roster'){return `<footer class="menu-footer"><span>${text}</span><span>18 Oct · UTC</span></footer>`}
function roster(accepted=false){return `<section aria-labelledby="roster-title"><div class="row"><h2 id="roster-title">On call now</h2><span class="small muted">Until ${F.menu.shiftEnd}</span></div><div class="roster">${F.menu.roster.map((p,i)=>{let name=accepted&&i===0?F.menu.handoverTo:p.name;return `<div class="person"><span class="avatar" aria-hidden="true">${name.split(' ').map(w=>w[0]).join('')}</span><div><div class="name">${esc(name)}${!accepted&&i===0?' <span class="muted">· you</span>':''}</div><div class="role">${esc(p.role)}</div></div></div>`}).join('')}</div></section>`}
function handover(accepted=false){return `<div class="handover" aria-label="${accepted?'Responsibility transferred from Jamie to Priya':'Jamie is responsible; Priya has not accepted'}"><div class="${accepted?'future':''}"><span class="avatar" aria-hidden="true">JE</span><strong>Jamie</strong><p>${accepted?'Handed over':'Responsible now'}</p></div><span class="arrow" aria-hidden="true">→</span><div class="${accepted?'':'future'}"><span class="avatar" aria-hidden="true">PR</span><strong>Priya</strong><p>${accepted?'Responsible now':'After acceptance'}</p></div></div>`}
function menu(){document.title=`Rota · ${state==='main'?'On call':state}`;let content='';
if(state==='main'||state==='offline')content=`${state==='offline'?'<div class="notice" role="status"><strong>You’re offline</strong><br>Last synced 09:42 UTC. This schedule may have changed.</div>':''}<section class="shift"><div class="eyebrow">${esc(F.menu.rotation)}</div><h1>${state==='offline'?'Last known: you’re on call':'You’re on call'}</h1><div class="row"><span class="muted">${esc(F.menu.user)}</span><strong>Until ${F.menu.shiftEnd}</strong></div><div class="time-track"><span>${F.menu.shiftStart}</span><span aria-hidden="true"></span><span>${F.menu.shiftEnd} UTC</span></div></section>${roster()}${state==='offline'?'<p class="small muted">Reconnect before handing over. Jamie remains responsible in the last known schedule.</p>':button('Hand over your shift','compose','primary wide')}`;
if(state==='compose'&&!review)content=`${button('‹ Back','main','quiet back')}<div><h1>Hand over your shift</h1><p class="subheading">${esc(F.menu.rotation)} · Until ${F.menu.shiftEnd} UTC</p></div><form id="handover-form" class="stack"><div class="form-field"><label for="recipient">Hand over to</label><select id="recipient" name="recipient" required><option value="">Choose a teammate…</option><option value="${esc(F.menu.handoverTo)}" ${recipient?'selected':''}>${esc(F.menu.handoverTo)}</option></select></div><div class="form-field"><label for="handover-note">Handover note <span class="muted small">(optional)</span></label><textarea id="handover-note" placeholder="What should Priya know?" maxlength="500">${esc(note)}</textarea></div><p class="small muted">You stay responsible until Priya accepts.</p><button class="primary wide" type="submit">Review handover</button></form>`;
if(state==='compose'&&review)content=`${button('‹ Edit handover','edit','quiet back')}<div><h1>Ready to hand over?</h1><p class="subheading">Priya will need to accept your request.</p></div>${handover()}<dl class="review-fact"><dt>Rotation</dt><dd>${esc(F.menu.rotation)}</dd><dt>Shift ends</dt><dd>${F.menu.shiftEnd} UTC today</dd>${note?`<dt>Your note</dt><dd>${esc(note)}</dd>`:''}</dl><div class="notice">Until Priya accepts, alerts and responsibility stay with you.</div><div class="actions">${button('Cancel','main')}${button('Send request','send','primary')}</div>`;
if(state==='pending')content=`<div><div class="eyebrow">Handover requested</div><h1 style="margin-top:var(--s-2)">Waiting for Priya</h1><p class="subheading">${esc(F.menu.rotation)} · Until ${F.menu.shiftEnd} UTC</p></div>${handover()}<div class="notice" role="status"><strong>You’re still on call.</strong><br>Keep responding to alerts until Priya accepts.</div><p class="small muted">Your request is for ${esc(F.menu.handoverTo)}. Responsibility changes only when they accept.</p>${button('Cancel request','cancel-request','wide')}${button('Back to schedule','pending-schedule','quiet wide')}`;
if(state==='accepted')content=`<div class="status-icon" aria-hidden="true">✓</div><div><h1>Handover complete</h1><p class="subheading">${esc(F.menu.handoverTo)} is now responsible for ${esc(F.menu.rotation)} until ${F.menu.shiftEnd} UTC.</p></div>${handover(true)}<p class="small muted" role="status">You’re off call for the rest of this shift.</p>${button('View current schedule','accepted-schedule','primary wide')}`;
if(state==='empty')content=`<div class="menu-empty"><div class="eyebrow">On-call schedule</div><h1>No shifts to show</h1><p class="muted">There’s no schedule available for your team. Ask your rotation owner to add a schedule.</p><p class="small muted">No handover can be made without a current shift.</p></div>${button('Back','main','wide')}`;
app.innerHTML=`<header class="menu-head row"><div class="brand">${icon()}<span class="brand-name">${F.menu.product}</span></div><span class="small muted">On call</span></header><div class="menu-content">${content}</div>${footer(state==='offline'?'Last known roster':'Current on-call roster')}`;
if(state==='compose'&&!review)document.querySelector('#handover-form').addEventListener('submit',e=>{e.preventDefault();recipient=document.querySelector('#recipient').value;note=document.querySelector('#handover-note').value.trim();if(!recipient)return;review=true;render();app.querySelector('h1').setAttribute('tabindex','-1');app.querySelector('h1').focus();});
}
let pendingSchedule=false,acceptedSchedule=false;
function dashboard(){const d=F.dashboard,stale=state==='stale',incidents=d.incidents.slice(0,state==='surge'?d.surgeCount:d.openCount);document.title=`${d.product} · ${stale?'Data delayed':incidents.length+' open'}`;
app.innerHTML=`<header class="dash-header"><div class="dash-brand">${icon('dash')}<h1>${esc(d.product)}</h1></div><div class="freshness ${stale?'':''}">${stale?`<span style="color:var(--warn)">Data delayed · As of ${d.staleAsOf}</span>`:'<span class="dot" aria-hidden="true"></span> Live snapshot'}</div><div class="dash-time"><strong>${d.displayTime}</strong>${d.displayDate}</div></header>${stale?`<div class="notice dash-warning" role="status"><strong>Updates interrupted.</strong> Last successful update ${d.staleAsOf}. Counts, incident status and on-call details below are last known, not current.</div>`:''}<section class="metrics" aria-label="Incident metrics"><div class="metric"><h2>${stale?'Last known open incidents':'Open incidents'}</h2><p class="value danger">${incidents.length}</p><p class="detail">${incidents.filter(i=>i.severity===1).length} critical · All unresolved statuses</p></div><div class="metric"><h2>Pages</h2><p class="value">${d.pages}</p><p class="detail">Change +${d.pagesDelta}</p></div><div class="metric"><h2>Mean time to resolve</h2><p class="value">${d.mttr}</p><p class="detail">${d.mttrChange}</p></div><div class="metric"><h2>SLO</h2><p class="value">${d.slo}</p><p class="detail">${d.sloChange}</p></div></section><div class="dashboard-layout"><section class="ledger" aria-labelledby="open-title"><div class="ledger-heading row"><h2 id="open-title">${stale?'Last known incidents':'Open incidents'}</h2><span>${incidents.length} total · Highest severity first</span></div><div role="table" aria-label="Open incidents"><div class="incident-head" role="row"><span role="columnheader">Incident</span><span role="columnheader">Summary / service</span><span role="columnheader">Status</span><span role="columnheader">Duration / opened</span><span role="columnheader">Commander</span></div>${incidents.map(i=>`<div class="incident" role="row"><div role="cell"><div class="incident-id">${i.id}</div><span class="severity sev-${i.severity}">SEV ${i.severity}</span></div><div role="cell"><p class="title">${esc(i.title)}</p><p class="service">${esc(i.service)}</p></div><div role="cell">${esc(i.status)}</div><div role="cell" class="duration">${i.duration}<span class="opened">${i.opened}</span></div><div role="cell" class="${i.commander?'':'missing'}">${i.commander?esc(i.commander):'Unassigned'}</div></div>`).join('')}</div></section><aside class="sidebar"><section><h2>${stale?'Last known on call':'On call'}</h2><div class="duty"><p>Primary</p><strong>${esc(d.primary)}</strong></div><div class="duty"><p>Secondary</p><strong>${esc(d.secondary)}</strong></div><p class="small muted" style="margin-top:var(--s-3)">Until ${d.until}</p></section><section><h2>Service activity</h2>${d.services.map(s=>`<div class="service-item"><span>${esc(s.name)}</span><strong class="mono">${s.value}</strong><div class="bar" aria-hidden="true"><i style="width:${s.value/d.services[0].value*100}%"></i></div></div>`).join('')}</section><section><h2>Recently resolved</h2>${d.resolved.map(i=>`<article class="resolved-item"><p class="mono">${i.id} · SEV ${i.severity}</p><h3>${esc(i.title)}</h3><p>${esc(i.service)}</p><p><span class="resolved">${i.status}</span> · ${i.duration}</p><p>Opened ${i.opened}</p></article>`).join('')}</section></aside></div><footer class="dash-footer">${stale?'Snapshot frozen at '+d.staleAsOf:'Snapshot at '+d.displayTime} · Incident times shown as supplied · Mitigated and monitoring incidents remain open.</footer>`;
}
function bankHeader(){return `<header class="bank-header"><div class="brand">${icon('bank')}${F.bank.name}</div>${button('Help','help','help-button')}</header>`}
function back(next){return button('Back',next,'quiet back')}
function bank(){const b=F.bank;document.title=`${b.name} · Account setup`;let content='',bottom='';
if(state==='welcome') {content=`<section><p class="step">Your everyday banking</p><h1>A simple start.<br>A fresh account.</h1><p class="intro">Let’s set up your ${b.accountName.toLowerCase()}.</p></section><ul class="benefits"><li><span class="tick" aria-hidden="true">✓</span><span>Enter your name and mobile number</span></li><li><span class="tick" aria-hidden="true">✓</span><span>Confirm it’s you with a text message</span></li><li><span class="tick" aria-hidden="true">✓</span><span>See your new account details</span></li></ul>${button('Get started','details','primary wide')}`;bottom='You’ll need a mobile phone that can receive text messages.';}
if(state==='details'||state==='details-error'){if(state==='details-error'&&!nameError&&!mobileError){nameError='Enter your full name, as it appears on your ID.';mobileError='Enter a UK mobile number, for example starting with 07.';}
content=`<section><p class="step">Step 1 of 2</p><h1>First, your details</h1><p class="intro">We’ll send a text message to confirm your mobile number.</p></section><form id="details-form" novalidate><div class="form-field"><label for="full-name">Full name</label><input id="full-name" name="name" autocomplete="name" value="${esc(customer)}" aria-describedby="name-hint${nameError?' name-error':''}" ${nameError?'aria-invalid="true"':''}><p id="name-hint" class="hint">As it appears on your ID</p>${nameError?`<p id="name-error" class="field-error">${nameError}</p>`:''}</div><div class="form-field"><label for="mobile">Mobile number</label><input id="mobile" name="mobile" type="tel" inputmode="tel" autocomplete="tel" value="${esc(mobile)}" aria-describedby="mobile-hint${mobileError?' mobile-error':''}" ${mobileError?'aria-invalid="true"':''}><p id="mobile-hint" class="hint">A UK number starting with 07 or +44</p>${mobileError?`<p id="mobile-error" class="field-error">${mobileError}</p>`:''}</div><button class="primary wide" type="submit">Send me a code</button></form>${back('welcome')}`;bottom='Your details are used to set up this account.';}
if(['code','code-error','help'].includes(state)){if(state==='code-error'&&!codeError)codeError='That code wasn’t right. Check your text message and try again.';
const end=mobile?mobile.replace(/\D/g,'').slice(-3):b.mobileEnding;
content=`<section><p class="step">Step 2 of 2</p><h1>Check your texts</h1><p class="intro">Enter the ${b.codeLength}-digit code sent to your mobile ending in <strong>${esc(end)}</strong>.</p></section><form id="code-form" novalidate><div class="form-field"><label for="sms-code">Text message code</label><input id="sms-code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="${b.codeLength}" pattern="[0-9]{${b.codeLength}}" aria-describedby="code-hint${codeError?' code-error':''}" ${codeError?'aria-invalid="true"':''} value="${esc(code)}"><p class="hint" id="code-hint">${b.codeLength} numbers, with no spaces</p>${codeError?`<p class="field-error" id="code-error" role="alert">${codeError}</p>`:''}</div><div class="safety"><strong>Keep your code safe</strong>${b.warning}</div><button class="primary wide" type="submit">Confirm code</button></form>${back('details')}`;bottom='No text message? Use Help to speak to us.';}
if(state==='done')content=`<div class="status-icon" aria-hidden="true">✓</div><section><h1>You’re all set, ${esc((customer||b.customer).split(' ')[0])}</h1><p class="intro">Your ${b.accountName.toLowerCase()} is ready.</p></section><section class="account" aria-label="Your account details"><h2>${b.accountName}</h2><dl><div><dt>Balance</dt><dd class="balance">${b.balance}</dd></div><div><dt>Sort code</dt><dd>${b.sortCode}</dd></div><div><dt>Account number</dt><dd>${b.accountNumber}</dd></div></dl></section>${button('Finish','finish','primary wide')}`;
app.innerHTML=`${bankHeader()}<div class="bank-content">${content}</div>${bottom?`<footer class="bank-footer">${bottom}</footer>`:''}<dialog id="help-dialog" aria-labelledby="help-title" aria-describedby="help-description"><h2 id="help-title">We’re here to help</h2><p id="help-description">Having trouble setting up your account? Speak to a person on our support team.</p><a class="phone" href="tel:${b.helpPhone.replace(/ /g,'')}">Call ${b.helpPhone}</a><p class="hint">${b.warning}</p><button class="primary" id="close-help">Back to setup</button></dialog>`;
const dialog=document.querySelector('dialog');document.querySelector('#close-help').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(state==='help'){state='code';params.set('screen','code');history.replaceState(null,'',`${location.pathname}?${params}`);}document.querySelector('[data-action="help"]').focus();});
if(state==='help'){dialog.showModal();document.querySelector('#close-help').focus();}
const df=document.querySelector('#details-form');if(df)df.addEventListener('submit',e=>{e.preventDefault();customer=document.querySelector('#full-name').value.trim();mobile=document.querySelector('#mobile').value.trim();nameError=customer.split(/\s+/).filter(Boolean).length>=2&&customer.length>2?'':'Enter your first and last name.';const digits=mobile.replace(/[\s()-]/g,'');mobileError=/^(07\d{9}|\+447\d{9})$/.test(digits)?'':'Enter a UK mobile number: 07 followed by 9 digits, or +44.';if(nameError||mobileError){go('details-error',false);document.querySelector('[aria-invalid="true"]').focus();}else {codeError='';go('code');}});
const cf=document.querySelector('#code-form');if(cf)cf.addEventListener('submit',e=>{e.preventDefault();code=document.querySelector('#sms-code').value.trim();if(code===b.testCode){code='';codeError='';go('done');}else{codeError=code.length!==b.codeLength?`Enter all ${b.codeLength} numbers from the text message.`:'That code wasn’t right. Check your text message and try again.';go('code-error',false);document.querySelector('#sms-code').focus();}});
}
function render(){if(family==='menu'){menu();if(pendingSchedule&&state==='main'){document.querySelector('.menu-content').insertAdjacentHTML('afterbegin','<div class="notice">Handover pending. You’re still responsible.</div>');const hand=app.querySelector('[data-action="compose"]');hand.textContent='View handover request';hand.dataset.action='pending';}if(acceptedSchedule&&state==='main'){document.querySelector('.menu-content').innerHTML=`<section class="shift"><div class="eyebrow">${F.menu.rotation}</div><h1>Priya is on call</h1><p>Until ${F.menu.shiftEnd} UTC · You’re off call</p></section>${roster(true)}`;}}else if(family==='dashboard')dashboard();else bank();}
app.addEventListener('click',e=>{const control=e.target.closest('[data-action]');if(!control)return;const action=control.dataset.action;
if(action==='help'){document.querySelector('dialog').showModal();return;}
if(action==='edit'){review=false;render();document.querySelector('#recipient').focus();return;}
if(action==='send'){pendingSchedule=true;go('pending');return;}
if(action==='cancel-request'){pendingSchedule=false;review=false;recipient='';go('main');return;}
if(action==='pending-schedule'){pendingSchedule=true;go('main');return;}
if(action==='accepted-schedule'){acceptedSchedule=true;pendingSchedule=false;go('main');return;}
if(action==='finish'){control.textContent='Setup complete';control.disabled=true;return;}
if(action==='main'){review=false;}go(action);
});
window.addEventListener('message',e=>{if(e.data==='simulate-acceptance'&&family==='menu'&&(state==='pending'||pendingSchedule)){pendingSchedule=false;acceptedSchedule=true;go('accepted');}});
render();
})();

*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:var(--fs-base)/var(--lh) var(--system);-webkit-font-smoothing:antialiased}button,input,select,textarea{font:inherit}button,a,input,select,textarea{touch-action:manipulation}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.6}a{color:var(--accent)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible,[tabindex]:focus-visible{outline:var(--ring) solid var(--accent);outline-offset:var(--focus-offset)}h1,h2,h3,p{margin:0}h1,h2,h3{line-height:var(--lh-tight)}button{border:var(--border) solid var(--line);border-radius:var(--r-sm);background:var(--surface);color:var(--fg);min-height:var(--desktop-target);padding:var(--s-2) var(--s-3);font-weight:600;transition:background var(--duration) var(--ease)}button:hover{background:var(--soft)}.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}.primary:hover{filter:brightness(.94);background:var(--accent)}.wide{width:100%}.quiet{background:transparent;border-color:transparent;color:var(--muted)}.text-button{border:0;background:transparent;color:var(--accent);padding:var(--s-2) 0;text-align:left}.muted{color:var(--muted)}.small{font-size:var(--fs-sm)}.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}.eyebrow{text-transform:uppercase;letter-spacing:.07em;font-size:var(--fs-xs);font-weight:650;color:var(--muted)}.row{display:flex;align-items:center;justify-content:space-between;gap:var(--s-3)}.stack{display:grid;gap:var(--s-3)}.rule{border-top:var(--border) solid var(--line)}.notice{padding:var(--s-3);border-radius:var(--r-sm);background:var(--warn-soft);color:var(--warn);font-size:var(--fs-md)}.notice.error{color:var(--danger);background:var(--danger-soft)}.notice.good{color:var(--good);background:var(--good-soft)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.mark{display:inline-flex;width:var(--mark);height:var(--mark);align-items:center;justify-content:center;color:var(--accent)}.mark svg{width:100%;height:100%}svg{fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
